def get_cell_band_pos(coord, sep_list):
    """Given coord and separator list, return (band_start, band_end)"""
    low = 0
    high = len(sep_list)
    while low < high:
        mid = (low + high) // 2
        if sep_list[mid] <= coord:
            low = mid + 1
        else:
            high = mid
    start = sep_list[low-1] if low > 0 else 0
    end = sep_list[low] if low < len(sep_list) else len(sep_list)
    return (start, end)

